import { useQuery } from "@tanstack/react-query";
import * as notificationsApi from "@/api/notificationsApi";
import type { NotificationListParams } from "@/api/notificationsApi";

// Read-only resource — no create/update/delete mutations, these rows are system-generated by the
// Kafka overdue-notification pipeline (see architecture.md's `OverdueNotificationConsumer`).
export function useNotificationsQuery(filters: NotificationListParams) {
  return useQuery({
    queryKey: ["notifications", filters],
    queryFn: () => notificationsApi.list(filters),
  });
}
